INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146179, 'spa', 'copa literal, recipiente para beber', 'copa literal, recipiente para beber');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146180, 'spa', 'copa metafórica de sufrimiento o juicio', 'copa metafórica de sufrimiento o juicio');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146181, 'spa', 'copa eucarística', 'copa eucarística');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146182, 'spa', 'oración', 'oración: acto o contenido de orar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146183, 'spa', 'lugar de oración (proseuché como sitio)', 'lugar de oración (proseuché como sitio)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146184, 'spa', 'Fuego literal', 'Fuego en su sentido fisico y cotidiano: combustion material como la fogata junto a la cual Pedro se calentaba en el patio del sumo sacerdote (Marcos 14:54; Lucas 22:55), o el fuego encendido por los nativos de Malta para Pablo y sus companeros (Hechos 28:2). Designa la llama tangible sin carga teologica directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146185, 'spa', 'Fuego escatologico y juicio', 'Fuego en su sentido escatologico y de castigo divino: la Gehena de fuego inextinguible (Mateo 5:22; 18:8-9; 25:41), el fuego probatorio que revela la calidad de cada obra (1 Corintios 3:13-15), el lago de fuego de Apocalipsis (Apocalipsis 20:14-15) y el bautismo en fuego anunciado por Juan el Bautista (Mateo 3:11). Abarca juicio, purificacion y destruccion apocaliptica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146186, 'spa', 'carne física, cuerpo material', 'La sustancia física del cuerpo humano o animal, incluyendo la carne literal, el cuerpo mortal como totalidad y la naturaleza humana en su finitud creatural. Abarca desde ''los dos serán una sola carne'' (Mateo 19:5) hasta la afirmación de la encarnación: ''el Verbo se hizo carne'' (Juan 1:14). El español ''carne,'' el francés ''chair'' y el alemán ''Fleisch'' preservan el mismo gradiente de lo literal a lo figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146187, 'spa', 'carne como naturaleza pecaminosa', 'La orientación no regenerada de la vida humana al margen del Espíritu de Dios, especialmente en el uso paulino. Pablo contrapone carne y Espíritu como dos principios rectores de la existencia (Romanos 8:4-9; Gálatas 5:16-17). Aquí ''carne'' designa no el tejido corporal sino la inclinación hacia el pecado y la autosuficiencia. El español mantiene ''carne'' pero el contexto teológico señala claramente este sentido ético-espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146188, 'spa', 'cuerpo físico', 'El cuerpo humano físico como un todo organizado, empleado para el cuerpo vivo (Mateo 6:22; Romanos 12:1), el cadáver (Mateo 27:58-59), y el cuerpo resucitado (1 Corintios 15:44). A diferencia de σάρξ (carne), σῶμα porta una valencia teológica positiva o neutra: el cuerpo es ''templo del Espíritu Santo'' (1 Corintios 6:19). El español ''cuerpo'' cubre uniformemente todos estos matices.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146189, 'spa', 'cuerpo de Cristo (eclesial)', 'Extensión metafórica paulina donde σῶμα designa a la iglesia como cuerpo corporativo de Cristo, con miembros diversos que desempeñan funciones distintas (1 Corintios 12:12-27; Efesios 1:23; Efesios 4:4). Esta metáfora orgánica enfatiza la unidad en la diversidad y la interdependencia mutua de los creyentes. El español mantiene ''cuerpo'' pero el contexto eclesiológico señala inequívocamente este sentido figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146190, 'spa', 'Fin temporal en sentido escatológico', 'Fin temporal en sentido escatológico: el punto final de una era o período, frecuentemente cargado de peso escatológico. Sentido dominante (36 ocurrencias) que aparece en el Discurso del Olivete: ''aún no es el fin'' (Mat 24:6; Mar 13:7) y ''el que persevere hasta el fin será salvo'' (Mat 10:22; 24:13). La expresión εἰς τέλος (''hasta el fin, completamente'') intensifica el sentido de plenitud y conclusión definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146191, 'spa', 'Cumplimiento, consumación o resultado final — no mera cesación, sino el punto en', 'Cumplimiento, consumación o resultado final — no mera cesación, sino el punto en que algo alcanza su plenitud. Pablo declara que Cristo es ''el τέλος de la ley'' (Rom 10:4), frase que oscila famosamente entre ''fin'' y ''cumplimiento''. Este sentido une terminación con realización plena del propósito divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146192, 'spa', 'padre biologico/legal', 'El padre inmediato — padre biologico, y por extension abuelo, suegro, padre adoptivo o cualquier figura de autoridad singular a quien se trata con respeto filial. Este sentido dominante (mas de 1.030 apariciones) abarca desde ''honra a tu padre'' (Ex 20:12) hasta la autoidentificacion de Jose como ''padre para Faraon'' (Gn 45:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146193, 'spa', 'padre metaforico', 'Uso metaforico: patron, consejero, protector u originador. Incluye la paternidad divina (''Padre nuestro''), la autoridad paternal de un lider sobre su pueblo o profesion, y el sentido de fundador o iniciador de un linaje, oficio o modo de vida. La amplitud de este uso refleja la centralidad de la figura paterna en la cosmovisión biblica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146194, 'spa', 'Edom (Esaú, persona)', 'Edom como sobrenombre personal de Esaú, el hermano gemelo de Jacob. La identificación explícita ''Esaú, el cual es Edom'' (Gn 36:1, 8) vincula al individuo con la raíz אדם (''rojo''), en alusión al guiso rojo por el que vendió su primogenitura (Gn 25:30). Este sentido aparece casi exclusivamente en los materiales genealógicos de Génesis 36.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146195, 'spa', 'Edom (nación y territorio)', 'Edom como pueblo y territorio: los descendientes de Esaú y la región montañosa que habitaron al sureste del Mar Muerto. Este sentido cubre la inmensa mayoría de las ocurrencias, abarcando desde las interacciones diplomáticas con Israel (Nm 20:18-21) hasta los oráculos proféticos de juicio (Abd; Jer 49). El nombre denota simultáneamente la identidad nacional y la entidad geográfica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146196, 'spa', 'tienda (morada común)', 'Una tienda ordinaria como vivienda portátil de nómadas, pastores o soldados. Desde las tiendas de los patriarcas (Gn 12:8; 18:1) hasta los campamentos militares y las tiendas de los hijos de Israel durante la peregrinación, este sentido designa el refugio cotidiano de tela o pieles, sin connotación sacra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146197, 'spa', 'Tabernáculo / Tienda de Reunión', 'La tienda sagrada donde Dios se encontraba con Israel: el Tabernáculo o Tienda de Reunión (אֹהֶל מוֹעֵד). Domina en Éxodo, Levítico y Números como centro del culto en el desierto, donde los sacerdotes ministran y la gloria divina se manifiesta. La expresión ''tienda de reunión'' se convierte en fórmula litúrgica central del sistema sacerdotal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146198, 'spa', 'tesorería, casa del tesoro', 'Recinto, edificio o cámara dedicada al almacenamiento de objetos valiosos — en particular la tesorería real o del templo. En Jos 6:19, los metales capturados van a la ''tesorería del SEÑOR,'' y 1 R 7:51 describe a Salomón depositando objetos en las tesorerías del templo. El énfasis recae en el lugar de almacenamiento más que en la riqueza almacenada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146199, 'spa', 'riqueza atesorada', 'Riqueza acumulada y guardada, con énfasis en su carácter de reserva o provisión almacenada. En contextos proféticos como Is 45:3, Dios promete entregar ''los tesoros escondidos,'' refiriéndose a las reservas de riqueza ocultas de las naciones. Esta acepción se solapa con el sentido 2 pero subraya más el aspecto de acumulación y custodia prolongada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146200, 'spa', 'luz física, luz del día', 'La luz como fenómeno físico: la luz diurna creada por Dios (Gn 1:3-5), la claridad matutina (Jue 16:2; 1 S 14:36) y la luminosidad de los cuerpos celestes (Is 30:26). Incluye toda referencia concreta a la iluminación natural en la narrativa, la poesía y la legislación bíblica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146201, 'spa', 'luz metafórica (vida, salvación)', 'La luz como símbolo de vida, favor divino, salvación y guía moral. En Job 3:20 el sufriente pregunta ''¿Por qué se da luz al miserable?,'' donde ''luz'' equivale a vida. El Sal 27:1 declara ''YHWH es mi luz y mi salvación.'' Pr 6:23 identifica la torá como luz, e Is 60:1 anuncia la gloria escatológica sobre Sion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146202, 'spa', 'a, hacia (movimiento)', 'Movimiento espacial hacia un punto, con matiz de aproximacion mas que de penetracion. Deuteronomio 31:7 envia a Josue ''hacia'' la tierra prometida. La distincion entre direccion y entrada es sutil pero real en contexto narrativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146203, 'spa', 'a (destinatario, dativo)', 'Sentido direccional primario: ''a'' o ''hacia'' una persona, lugar o cosa. Con mas de 5.300 apariciones, domina la prosa hebrea. Genesis 1:9 reune las aguas ''a un solo lugar''. Acompana todo verbo de movimiento y discurso, marcando destino o destinatario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146204, 'spa', 'Dios (de Israel, YHWH)', 'El Dios de Israel: sentido abrumadoramente dominante que abarca a Dios como creador, pactante, legislador, juez y redentor. Se usa con articulo (הָאֱלֹהִים), en cadenas constructas (אֱלֹהֵי יִשְׂרָאֵל), con sufijos pronominales (אֱלֹהֵינוּ, ''nuestro Dios'') y tras preposiciones. Concuerda con verbos en singular pese a su morfologia plural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146205, 'spa', 'dioses (deidades paganas)', 'Dioses de las naciones en sentido plural genuino, donde אֱלֹהִים designa colectivamente a las deidades de los pueblos circundantes. ''Quitad los dioses ajenos'' (Gn 35:2), ''no tendras dioses ajenos'' (Ex 20:3). Las glosas interlingüisticas despliegan uniformemente sus formas plurales estandar para deidades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146206, 'spa', 'ira divina, furor', 'La ira de Dios expresada mediante אַף, predominantemente en la frase חֲרוֹן אַף (''ardor de ira''). Aparece de forma abrumadora en contextos de juicio divino (Éx 32:12; Nm 25:4; Dt 29:24). La imagen subyacente es de narices dilatadas y aliento en ráfagas ardientes, aunque el origen anatómico queda completamente abstraído en la mayoría de los contextos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146207, 'spa', 'ira humana, enojo', 'La ira o el enojo atribuidos a seres humanos. Génesis 30:2 registra que ''se encendió la ira de Jacob''; Gn 49:6 maldice la ira de Simeón y Leví. Aunque la metáfora de base es la misma que para la ira divina, el sujeto humano distingue este sentido, y las traducciones multilingües mantienen uniformemente vocabulario de ira: español ''ira'', árabe غَضَب.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146208, 'spa', 'país, territorio', 'Tierra como territorio geopolítico: el país, la región o el dominio de una nación. Es la acepción dominante en las fórmulas de alianza (''la tierra de Canaán'', ''la tierra que juré a vuestros padres''), donde geografía y promesa divina se entrelazan inseparablemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146209, 'spa', 'suelo, terreno', 'Tierra como superficie física o suelo sobre el cual se camina, se cae o se postra. Aparece en contextos donde lo táctil e inmediato predomina: alguien cae ''a tierra'', se inclina rostro ''en tierra'', o se siembra ''en la tierra''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146210, 'spa', 'suelo, superficie', 'Suelo o superficie bajo los pies, con énfasis en el contacto físico con el terreno. Aparece con verbos de movimiento descendente o postración, donde la referencia concreta al piso resulta prominente frente a cualquier sentido territorial o cósmico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146211, 'spa', 'la tierra, el mundo', 'La tierra como totalidad del mundo habitado o creado, con matiz más amplio que el territorial. Aparece en declaraciones universales sobre el dominio divino y el destino de toda la humanidad, donde ''tierra'' equivale prácticamente a ''mundo entero''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146212, 'spa', 'fuego ordinario, físico', 'Fuego literal y físico en todos sus usos prácticos: combustión, llamas, conflagración, fuego de cocina, fuego sacrificial, fuego de señales, fuego destructivo en la guerra y calor doméstico. Con 345 apariciones, esta acepción cubre la gran mayoría de los usos, desde el fuego del pacto de Abraham (Gn 15:17) hasta las ofrendas levíticas ''por fuego'' (Lv 1:7-9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146213, 'spa', 'fuego de presencia divina', 'Fuego como presencia o juicio divinos en sentido general, cuando el contexto señala un origen sobrenatural sin encajar exclusivamente en teofanía, castigo o fenómeno celeste. Funciona como categoría puente que engloba las manifestaciones del fuego divino no diferenciadas con mayor precisión por el contexto inmediato.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146214, 'spa', 'Asera la diosa (deidad) — referencia directa a la diosa Asera como entidad divin', 'Asera la diosa (deidad) — referencia directa a la diosa Asera como entidad divina, sin metonimia hacia el objeto de culto. En estos contextos el nombre funciona como teónimo propio de la deidad cananea venerada junto a Baal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146215, 'spa', 'Poste o imagen de Asera (objeto de culto) — el objeto físico de culto', 'Poste o imagen de Asera (objeto de culto) — el objeto físico de culto: un poste de madera, imagen tallada o árbol sagrado estilizado erigido junto a los altares cananeos y los lugares altos israelitas. Casi siempre aparece en plural ''Asherim'' junto a ''pilares'' (masseboth) en mandatos de destrucción (Éx 34:13; Dt 7:5; Jue 6:25-26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146216, 'spa', 'entrar (espacio físico)', 'Sentido Qal con matiz de penetración espacial: entrar en un espacio cerrado o delimitado — arca, casa, ciudad, tienda, tierra prometida. Se distingue del sentido 1 por la contención espacial: no se trata de llegar a un punto abierto, sino de cruzar un umbral. Español distingue entró de vino; árabe usa دخل; suajili, kuingia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146217, 'spa', 'eufemismo sexual', 'Uso eufemístico con la preposición אֶל para designar la relación sexual: ''entrar a'' una mujer. Expresión idiomática frecuente en narrativas patriarcales y legales. El español traduce entró a, el francés vint vers, y el árabe دخل على, todos preservando la metáfora espacial del cruce de un umbral íntimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146218, 'spa', 'Pozo, hoyo o cavidad literal en el suelo — ya sea natural o excavado deliberadam', 'Pozo, hoyo o cavidad literal en el suelo — ya sea natural o excavado deliberadamente. Incluye fosos para atrapar animales o enemigos, como el pozo donde fue arrojado José (Gn 37:20-29), imagen poderosa del terror de caer en un agujero vacío. El árabe بُئْرَة (hoyo para cocinar) conserva el sentido raíz de un espacio cavado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146219, 'spa', 'Pozo metafórico', 'Pozo metafórico: Seol, muerte, sepultura — en textos poéticos y proféticos, ''los que descienden al pozo'' (Is 38:18; Sal 28:1) significa descender a la muerte misma. La imagen concreta del foso se transforma en símbolo del reino de los muertos, el destino final de donde no se regresa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146220, 'spa', 'hijo (descendencia directa)', 'Descendencia masculina en sentido biológico o legal directo, incluidos los descendientes. Este significado nuclear de parentesco predomina en genealogías y narrativas. Las traducciones multilingües emplean uniformemente las palabras básicas para hijo varón: español hijo, árabe اِبْن, hindi बेटा/पुत्र, suajili mwana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146221, 'spa', 'miembro de una clase', 'Expresión idiomática constructa ''hijo/hijos de X'' que denota pertenencia a una clase o posesión de una cualidad, no filiación literal. ''Hijos de los profetas'' son miembros del gremio, ''hijos de Belial'' son malvados. El suajili cambia a watu wa (''gente de''), revelando la función categorial bajo la metáfora de parentesco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146222, 'spa', 'Hierro (metal, herramientas, armas, material)', 'Hierro (metal, herramientas, armas, material): hierro como mineral extraído de la piedra (Dt 8:9; Job 28:2), como metal trabajado para fabricar herramientas, armas y carros (Jos 17:16; Jue 4:3), y como artículo de comercio (Ez 27:12, 19). Abarca todos los usos materiales y concretos del término en la Biblia hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146223, 'spa', 'Hierro (figurado', 'Hierro (figurado: fuerza, dureza, severidad): uso metafórico donde el hierro se convierte en la imagen bíblica por excelencia de la dureza y la opresión — el «horno de hierro» de Egipto (Dt 4:20), el «yugo de hierro» de la servidumbre (Dt 28:48) y la «vara de hierro» del dominio soberano (Sal 2:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146224, 'spa', 'cuerpo, ser corporal', 'El cuerpo individual, el ser corpóreo en contraposición al espíritu, el alma o la vida interior. ''Toda carne'' (כָּל בָּשָׂר) es un modismo estándar para todos los seres vivientes o toda la humanidad (Gn 6:12-13, 17). El sentido de cuerpo-como-persona se confirma interlingüísticamente: el suajili mwili, el hindi शरीर y el coreano 육체 seleccionan vocabulario de ''cuerpo/ser físico''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146225, 'spa', 'toda carne, humanidad', 'Uso colectivo que designa a la humanidad o a todas las criaturas vivientes en conjunto. Frecuente en la fórmula כָּל בָּשָׂר (''toda carne''), ya sea en contextos de juicio universal (Gn 6:12-13) o de promesa escatológica (Is 40:5; Jl 2:28). El suajili wote walio hai y el árabe كُلُّ بَشَر lo confirman como designación colectiva de la fragilidad creatural ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146226, 'spa', 'tejido físico, carne literal', 'Carne literal humana o animal como tejido físico — la materia corporal misma, distinta tanto del cuerpo como totalidad como de la carne en cuanto alimento. Incluye referencias al tejido muscular y orgánico en contextos de herida, descomposición o descripción anatómica. Un sentido que subraya la materialidad cruda del ser viviente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146227, 'spa', 'carne comestible, alimento', 'Carne comestible — tejido animal como alimento, material sacrificial o sustancia física, con unas 49 apariciones. Las instrucciones de la Pascua especifican comer la בָּשָׂר asada (Ex 12:8); los israelitas anhelan בָּשָׂר en el desierto (Nm 11:4-13); los sacerdotes consumen la בָּשָׂר de la ofrenda de paz (Ex 29:31-32). El coreano 고기 y el suajili nyama seleccionan consistentemente vocabulario dedicado a ''carne/alimento''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146228, 'spa', 'Virgen literal', 'Virgen literal: mujer joven soltera cuya característica definitoria es la virginidad — vive en la casa de su padre, sin haber conocido varón (Gn 24:16). Los textos legales prescriben normas matrimoniales para la בְּתוּלָה (Dt 22:19, 23, 28), y el sumo sacerdote debe casarse con una (Lv 21:13-14). Joel 1:8 evoca memorablemente a una בְּתוּלָה que llora al esposo de su juventud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146229, 'spa', 'Virgen figurada', 'Virgen figurada: ciudades y naciones personificadas como «virgen» — típicamente para expresar vulnerabilidad, pureza o el patetismo de la devastación. Los profetas personifican naciones enteras como «virgen Israel» (Am 5:2; Jer 31:4) y «virgen hija de Sion» (2 R 19:21; Lm 2:13). La imagen transmite tanto la pureza ideal como la fragilidad ante la conquista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146230, 'spa', 'palabra, discurso', 'El sentido primario: una palabra hablada o escrita, un oráculo divino o un mensaje profético. Domina con 1.235 apariciones e incluye la fórmula «vino palabra del SEÑOR a» (Gn 15:1; 1 S 3:7; 1 S 15:10), columna de la revelación profética en toda la Biblia hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146231, 'spa', 'asunto, cosa, suceso', 'Asuntos, cosas o sucesos: un objeto de discusión o una realidad concreta que requiere atención. Aparece en contextos legales donde «asuntos» que exigen juicio incluyen disputas concretas (Dt 17:8) y en pasajes narrativos donde דָּבָר designa la realidad referida más que la palabra que la nombra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146232, 'spa', 'sangre (fluido literal)', 'El fluido rojo literal de humanos y animales, abarcando la sangre sacrificial aplicada a altares y dinteles (Éx 12:7, 13, 22; Lv 4:30), la prohibición dietética de consumir sangre (Gn 9:4; Lv 17:11-14), sangre de heridas y matanza en batalla, y sangre menstrual o postparto (Lv 12:7). Este sentido abrumadoramente mayoritario converge en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146233, 'spa', 'violencia, derramamiento', 'Derramamiento de sangre, violencia o asesinato por metonimia, donde la sangre representa el acto de matar más que la sustancia misma. Frecuentemente marcado por el plural דָּמִים, como en ''ciudad de sangres'' (Nah 3:1; Ez 22:2) o ''sangre inocente'' derramada injustamente (Dt 19:10; Jer 22:3). El clamor de la sangre de Abel (Gn 4:10-11) es el caso paradigmático.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146234, 'spa', 'culpa de sangre (jurídico)', 'Culpa de sangre o responsabilidad jurídica incurrida por derramar sangre. Aparece en fórmulas legales: ''su sangre sea sobre él'' (Lv 20:9), ''su sangre sea sobre su cabeza'' (Jos 2:19; 2 S 1:16), y la súplica de David ''líbrame de culpas de sangre'' (Sal 51:14[16]). Se distingue de la mera violencia por su carácter de imputación legal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146235, 'spa', 'camino, vía (físico)', 'Variante del sentido concreto que designa una vía o ruta transitada, con énfasis en el espacio geográfico. Incluye caminos específicos mencionados en la narrativa bíblica y rutas de peregrinación o desplazamiento militar. La evidencia interlingüe confirma uniformemente la lectura espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146236, 'spa', 'modo de vida, conducta', 'Modo de vida, conducta moral o comportamiento habitual: la gran extensión metafórica del vocablo. Dios examina los «caminos» humanos (Gn 6:12; Sal 139:3), ordena a su pueblo caminar en sus «caminos» (Dt 8:6; 10:12) y los impíos se definen por sus «caminos» (Sal 1:6; Pr 4:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146237, 'spa', 'sacrificar a YHWH', 'El acto de ofrecer un sacrificio animal al Señor en contextos de adoración legítima: festividades, cumplimiento de votos, acción de gracias y ritos de pacto. Este es el uso central y positivo del verbo, vinculado al sistema sacrificial prescrito en la Torá y practicado desde los patriarcas hasta el Templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146238, 'spa', 'sacrificar a ídolos', 'Ofrecer sacrificios a dioses falsos o ídolos, sentido que aparece con frecuencia en los textos proféticos y en las narraciones de apostasía. Los profetas denuncian repetidamente a Israel por sacrificar en los lugares altos a Baal y a otras deidades. El vocabulario es idéntico al del sacrificio legítimo; solo el destinatario cambia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146239, 'spa', 'Prostituta secular (זוֹנָה)', 'Prostituta secular (זוֹנָה): la prostituta en sentido literal, una mujer que ejerce el comercio sexual. Incluye a Rajab la ramera (Jos 2:1, 6:17), las dos prostitutas ante Salomón (1 R 3:16) y las referencias legales. Se traduce al español como ''ramera'' o ''prostituta''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146240, 'spa', 'Ramera metafórica (infidelidad espiritual)', 'Ramera metafórica (infidelidad espiritual): el uso figurado del sustantivo זוֹנָה aplicado a ciudades o naciones personificadas como rameras por su infidelidad al pacto. Jerusalén es llamada ''ramera'' (Is 1:21), y Nínive y Tiro reciben el mismo epíteto. Se distingue del sentido 2 por su referente colectivo y teológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146241, 'spa', 'Brazo literal (parte del cuerpo)', 'Brazo literal (parte del cuerpo): el brazo humano como parte física del cuerpo, desde el hombro hasta la mano. Usado para describir acciones concretas: Sansón rompe las cuerdas de sus brazos (Jue 15:14), los brazos de las manos de Jacob son fortalecidos (Gn 49:24). Árabe ذِرَاع, suajili mkono y francés bras convergen en el miembro corporal literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146242, 'spa', 'Brazo de Dios (metáfora de poder divino)', 'Brazo de Dios (metáfora de poder divino): el uso metafórico abrumadoramente dominante: el ''brazo extendido'' (זְרוֹעַ נְטוּיָה) de Dios liberando a Israel de Egipto aparece como fórmula fija en Deuteronomio (4:34; 5:15; 7:19; 26:8) y se convirtió en piedra angular de la teología del éxodo. Con 85 ocurrencias, es la acepción central de esta palabra en la Biblia hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146243, 'spa', 'nuevo, hecho recientemente (objetos físicos)', 'nuevo, hecho recientemente (objetos físicos)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146244, 'spa', 'nuevo (renovación teológica/escatológica)', 'nuevo (renovación teológica/escatológica)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146245, 'spa', 'sabio (adjetival general)', 'Uso adjetival que describe la posesión de sabiduría en contextos donde el término funciona como modificador genérico más que como título social. Cubre casos donde la frontera entre adjetivo y sustantivo resulta difusa, como en las colecciones sapienciales de Proverbios donde ''los sabios'' y ''el sabio'' alternan entre referencia a una cualidad y a una clase.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146246, 'spa', 'sabios, consejeros (clase)', 'Uso sustantivado para designar una clase social reconocida de sabios, consejeros o asesores cortesanos — 48 ocurrencias. En Gn 41:8 Faraón convoca a ''todos los sabios de Egipto'' junto con los magos; en Éx 7:11 los חֲכָמִים aparecen como clase profesional paralela a los hechiceros; Jeremías 18:18 enumera el consejo ''del sabio'' junto con la instrucción del sacerdote y la visión del profeta, confirmando su función institucional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146247, 'spa', 'rocio (humedad atmosferica literal)', 'rocio (humedad atmosferica literal)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146248, 'spa', 'rocio (simbolo de bendicion divina)', 'rocio (simbolo de bendicion divina)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146249, 'spa', 'Ritualmente impuro — Impuro ceremonialmente según la ley levítica', 'Ritualmente impuro — Impuro ceremonialmente según la ley levítica: animales prohibidos para consumo y sacrificio (Lv 11:4-8; Dt 14:7-8), personas contaminadas por enfermedad cutánea, flujo corporal o contacto con cadáveres (Lv 13–15; Nm 19), y objetos o lugares que han sido contaminados. Este sentido domina el uso y estructura la legislación de pureza de Levítico y Números.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146250, 'spa', 'Moralmente contaminado — Impureza moral o espiritual que trasciende lo ceremonia', 'Moralmente contaminado — Impureza moral o espiritual que trasciende lo ceremonial. Isaías confiesa tener «labios impuros» (Is 6:5), no como categoría ritual sino como imagen de pecado e indignidad ante Dios. Lamentaciones 4:15 describe a los sacerdotes como «inmundos» por la sangre derramada. Este sentido metafórico extiende el lenguaje de pureza al ámbito ético y espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146251, 'spa', 'Secarse, quedar seco (de fuentes de agua) — el sentido intransitivo aplicado esp', 'Secarse, quedar seco (de fuentes de agua) — el sentido intransitivo aplicado específicamente a ríos, arroyos y otras fuentes de agua que pierden su caudal y quedan secos, como en el relato del diluvio (Gn 8:7, 14) y los oráculos proféticos de sequía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146252, 'spa', 'Marchitarse, secarse (de vegetación y tejido vivo) — el sentido intransitivo de ', 'Marchitarse, secarse (de vegetación y tejido vivo) — el sentido intransitivo de marchitarse o secarse aplicado a plantas, hierba y materia orgánica. La imagen es fundamental en la poesía bíblica: ''la hierba se seca, la flor se marchita'' (Is 40:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146253, 'spa', 'mano (parte del cuerpo)', 'La mano como parte física del cuerpo humano en sentido concreto y literal: la mano que toca, sostiene, levanta o impone. Gn 3:22 (''extienda su mano''), Gn 24:2 (''pon tu mano debajo de mi muslo''). Las traducciones multilingües mantienen uniformemente el equivalente literal: español ''mano'', francés ''main'', alemán ''Hand''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146254, 'spa', 'mano (poder, agencia)', 'La mano como instrumento de poder, dominio y agencia, sentido dominante con 1.596 apariciones. El árabe يَدٌّ, el arameo יְדָא y el etiópico እድ preservan la raíz semítica compartida. Abarca ''mano de Dios'' (poder), ''en mano de'' (custodia), ''por mano de'' (agencia). Base de decenas de modismos hebreos (Gn 27:17; 39:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146255, 'spa', 'mano derecha (parte corporal)', 'La mano derecha como parte física del cuerpo, la mano de habilidad y bendición. En Génesis 48:13-14, José coloca a sus hijos para que la mano derecha de Jacob caiga sobre el primogénito. Aquí el sentido es puramente anatómico, sin la carga teológica de la diestra divina ni la función direccional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146256, 'spa', 'diestra (poder divino/real)', 'La mano derecha como instrumento del poder y la autoridad divina o real (62 apariciones). Es la yamin de Éxodo 15:6, ''Tu diestra, oh SEÑOR, es gloriosa en poder'', y del Salmo 110:1, donde el rey se sienta a la diestra de Dios. El español diestra (frente a derecha) capta esta carga teológica de agencia, protección y honra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146257, 'spa', 'temer, tener miedo', 'La acepción dominante (239 apariciones): miedo visceral o pavor provocado por peligro, enemigos o teofanías divinas. La reiterada exhortación divina ''al tira'' (''no temas'', Gn 15:1; 21:17; 46:3) presupone precisamente esta alarma involuntaria, convirtiéndola en el uso más frecuente en toda la Biblia hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146258, 'spa', 'temer, reverenciar a Dios', 'Temor reverencial dirigido a Dios o a la autoridad soberana (25 apariciones): la postura sostenida y piadosa de adoración y obediencia, no un susto momentáneo. Mandatos como ''Temerás al SEÑOR tu Dios'' (Dt 6:13) y ''Temerás a tu madre y a tu padre'' (Lv 19:3) ilustran la reverencia ética, no el pánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146259, 'spa', 'los que descienden al Seol', 'Participio activo Qal usado sustantivamente (44 apariciones), especialmente en la fórmula recurrente ''yorde bor'' (los que descienden a la fosa/Seol). La literatura poética y profética favorece esta expresión formularia, traducida como los que descienden, those going down.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146260, 'spa', 'descendiendo (uso participial)', 'Participio Qal en uso general (15 pasajes) que describe acciones en curso de descenso, tanto de personas como de elementos en movimiento. El participio funciona adverbial o adjetivalmente según el contexto, manteniendo la direccionalidad descendente característica del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146261, 'spa', 'plata como material', 'La plata como sustancia física: metal precioso en bruto, refinado o trabajado. Aparece en descripciones de objetos materiales, adornos y referencias al metal mismo, sin connotación monetaria. El español plata y el alemán Silber captan directamente el referente material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146262, 'spa', 'plata como dinero', 'La plata en su función monetaria: moneda, medio de cambio o precio de compra. Los contextos comerciales y transaccionales predominan, donde la plata se pesa y se cuenta como pago. Las traducciones en alemán alternan entre Silber (sustancia) y Geld (dinero), reflejando esta distinción semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146263, 'spa', 'muy, sumamente', 'Adverbio de grado que significa ''muy,'' ''sumamente'' o ''en gran manera,'' empleado para intensificar adjetivos (Gn 1:31, ''muy bueno''), verbos (Gn 4:5, ''se enfureció en gran manera'') y cantidades (Gn 7:18-19). Este es el uso dominante con 299 de las 301 ocurrencias. Las traducciones multilingües (esp. muy, fr. très, al. sehr) confirman su rendimiento uniforme como intensificador de grado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146264, 'spa', 'fuerza, capacidad plena', 'Uso nominal que denota ''fuerza,'' ''capacidad'' o ''plenitud de recursos.'' Aparece en Deuteronomio 6:5, donde se ordena amar a Dios ''con todo tu מְאֹד,'' es decir, con la totalidad de lo que uno posee y puede dar. El español oscila entre ''fuerza'' y ''todo tu ser,'' mientras que el Targum traduce con mamón (''riquezas''). Este sentido sustantivo transforma un simple intensificador en un concepto teológico de entrega absoluta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146265, 'spa', 'muerte como evento', 'La muerte como acontecimiento o proceso: el acto concreto de morir, el momento en que la vida cesa. Es la acepción más frecuente, abarcando muertes naturales, violentas y referencias al fallecimiento de individuos nombrados. El árabe mawt y el coreano 죽음 se centran igualmente en este cese concreto de la vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146266, 'spa', 'pena capital', 'La muerte como sanción penal en sentido estricto, referida específicamente a la ejecución por delito. Aunque se solapa parcialmente con la acepción anterior, aquí el énfasis recae en el marco legal y la imposición formal del castigo máximo según la ley mosaica o la autoridad real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146267, 'spa', 'rey (soberano humano)', 'Un soberano o monarca humano que gobierna una ciudad-estado, nación o imperio. Abarca los reyes israelitas (Saúl, David, Salomón), los reyes extranjeros (Faraón, Nabucodonosor, Ciro) y los reyezuelos de Canaán. La uniformidad interlingüística es notable: cada lengua emplea su término real básico sin calificación alguna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146268, 'spa', 'Rey (título divino)', 'Dios como Rey divino, un título teológico que expresa la soberanía suprema del SEÑOR. Las glosas multilingües adoptan formas posesivas y devocionales —''mi Rey'', ''nuestro Rey'', ''mein König''— marcando la relación personal y pactual entre Dios como Rey y su pueblo. Concentrado en los Salmos: ''He establecido a mi Rey en Sion'' (Sal 2:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146269, 'spa', 'artesanía del tabernáculo', 'Obra artesanal sagrada: el trabajo especializado de los artífices del tabernáculo. Cada cortina, candelabro y vestidura sacerdotal se describe como מַעֲשֶׂה, designando la hechura cualificada de los objetos rituales (Éx 26-28). Es la acepción dominante en los textos sacerdotales del Pentateuco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146270, 'spa', 'obra de manos (ídolos)', 'Obra de manos humanas, especialmente ídolos u objetos manufacturados. La expresión מַעֲשֵׂה יְדֵי אָדָם denuncia la fabricación de imágenes como acto de idolatría. Este sentido concentra la ironía profética: lo que el hombre fabrica, luego adora como si tuviera poder propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146271, 'spa', 'Serpiente como reptil literal y peligro natural', 'Serpiente como reptil literal y peligro natural. Incluye las «serpientes ardientes» del desierto (Nm 21:6), la serpiente que muerde junto al camino (Gn 49:17), y las serpientes como amenaza repentina y mortal (Am 5:19; Ec 10:8). El referente es zoológico: un animal venenoso y temido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146272, 'spa', 'Serpiente como tentador arquetípico y enemigo cósmico', 'Serpiente como tentador arquetípico y enemigo cósmico. En Génesis 3:1-14 es la criatura astuta que tienta en el Edén; en Isaías 27:1 se extiende a la figura del monstruo marino escatológico. Este sentido trasciende lo zoológico para representar la oposición al propósito divino y la fuente primordial de engaño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146273, 'spa', 'adorar, servir a YHWH', 'Adorar o servir a una deidad en sentido religioso o de pacto, con diferencia el uso dominante (203 veces). Cubre tanto la adoración legítima de YHWH (Éx 10:11, 26; Nm 4:24) como el servicio idolátrico a dioses extranjeros, convirtiéndolo en el verbo clave de la fidelidad y la apostasía pactual a lo largo de Deuteronomio y los libros históricos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146274, 'spa', 'servir a dioses ajenos', 'Servir o ministrar a dioses extranjeros o ídolos en un sentido de culto impropio. Jacob sirve a Labán por Raquel (Gn 29:18, 25, 27), vasallos sirven a señores (Gn 14:4) y a Esaú se le dice que servirá a su hermano (Gn 27:40): todo servicio relacional y jerárquico que el contexto desvía hacia la idolatría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146275, 'spa', 'eterno (pactos y ordenanzas)', 'Uso atributivo referido a pactos y ordenanzas divinas: ''pacto eterno'' (berit olam), ''estatuto perpetuo'' (juqqat olam). Califica las instituciones establecidas por Dios como permanentes e inviolables, subrayando la fidelidad divina que trasciende las generaciones humanas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146276, 'spa', 'perpetuo, perdurable', 'Uso atributivo general: ''perpetuo, perdurable, duradero'', aplicado a realidades que no son específicamente pactos ni ordenanzas divinas, sino posesiones, herencias, fronteras y condiciones que se conciben como permanentes. La modificación adjetival marca un desplazamiento del adverbio temporal (''para siempre'') al calificativo estable (''eterno, perpetuo'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146277, 'spa', 'sobre, en (contacto físico)', 'Sentido espacial central: literalmente «encima de» o «sobre». 5,443 de 5,769 ocurrencias. Ejemplos: «Abraham se postró sobre su rostro» (Gén 17:17). Expresa contacto directo con una superficie.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146278, 'spa', 'sobre, por encima de (superioridad)', 'Sentido adversativo o de dominio aunque etiquetado como «sobre». 120 ocurrencias. Indica superioridad vertical, autoridad o dominio sobre algo o alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146279, 'spa', 'perdurar, persistir', 'Perdurar, persistir o mantenerse a lo largo del tiempo: extensión metafórica donde la postura física se convierte en figura de permanencia. Las promesas que ''permanecerán'', los decretos que ''se mantendrán en pie'' y las realidades que subsisten más allá de su contexto inmediato se expresan con este sentido temporal del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146280, 'spa', 'resistir, mantenerse firme', 'Mantenerse firme frente a la oposición, resistir. ''¿Quién podrá estar en pie delante del Señor?'' (1 S 6:20) y ''nadie podrá resistir delante de ti'' (Jos 10:8) ejemplifican este sentido. La postura física se convierte en metáfora de entereza y capacidad de resistencia ante fuerzas adversas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146281, 'spa', 'La nube teofánica que manifiesta la presencia de Dios — la columna de nube que g', 'La nube teofánica que manifiesta la presencia de Dios — la columna de nube que guía a Israel (Éx 13:21-22), la densa nube sobre el Sinaí (Éx 19:9, 16) y la nube de gloria que llena el tabernáculo y el templo (1 R 8:10-11). Este sentido domina la mayoría de las 87 ocurrencias, marcando los momentos más solemnes de revelación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146282, 'spa', 'Nube meteorológica ordinaria o fenómeno atmosférico natural, sin connotación teo', 'Nube meteorológica ordinaria o fenómeno atmosférico natural, sin connotación teofánica directa. Incluye referencias a nubes de lluvia (1 R 18:44), nubes que cubren el cielo (Ec 12:2) y el uso figurado de la nube como imagen de lo transitorio (Os 6:4 ''como nube matutina'') o de lo que oculta (Job 26:9, Dios ''cubre la faz de su trono con una nube'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146283, 'spa', 'Desnudez corporal literal, exposición física del cuerpo', 'Desnudez corporal literal, exposición física del cuerpo. Cam ve la desnudez de Noé (Gn 9:22-23), y la vergüenza del estado desvestido se asocia con la vulnerabilidad. Este sentido abarca la mera falta de vestimenta sin implicar necesariamente transgresión sexual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146284, 'spa', 'Relaciones sexuales ilícitas (uso eufemístico)', 'Relaciones sexuales ilícitas (uso eufemístico): la frase legal ''descubrir la desnudez de'' funciona como el modismo estándar para las uniones sexuales prohibidas en Levítico 18-20. La construcción aparece de forma formulaica en el código de santidad, cubriendo incesto, adulterio y otras transgresiones sexuales tipificadas en la ley mosaica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146285, 'spa', 'rostro, semblante', 'El rostro como parte del cuerpo, incluyendo las expresiones faciales y el semblante. Las traducciones usan vocabulario anatómico específico (español rostro/faz, árabe وَجْهَ, hindi मुँह). Se distingue claramente de las extensiones metafóricas por su referencia concreta a la fisonomía humana o animal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146286, 'spa', 'delante de, en presencia de', 'Sentido locativo-relacional: ''ante'', ''delante de'', ''en presencia de''. Las traducciones multilingües emplean consistentemente preposiciones de ubicación relativa (español ante/delante de, francés devant, árabe أَمَامَ). Indica la posición de alguien o algo frente a otra entidad, frecuentemente con matiz teológico de acceso o comparecencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146287, 'spa', 'rostro físico literal', 'El rostro en su acepción más concreta y corporal: la cara visible de una persona o animal como parte anatómica. Sin extensión metafórica, refiere estrictamente al aspecto físico del semblante, incluyendo los rasgos faciales como objeto de descripción o percepción directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146288, 'spa', 'antes, anteriormente', 'Sentido temporal: ''antes de'', ''anteriormente'', ''en tiempos pasados'', derivado de la metáfora espacial de lo que está delante de uno. Las traducciones recurren a adverbios temporales (español antes/antiguamente, francés autrefois, alemán früher), marcando la transición del espacio al tiempo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146289, 'spa', 'Ejército humano', 'Ejército humano o fuerza militar organizada: tropas reunidas y dispuestas para la batalla. Es el sentido más frecuente y aparece formulaicamente en los censos tribales de Números 1-2. El árabe ŷayš y el alemán Heer capturan esta acepción de fuerza armada terrenal convocada bajo mando.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146290, 'spa', 'Hueste celestial', 'La hueste celestial: fuerzas angélicas o cuerpos celestes bajo el mando divino. En el título ''YHWH de los ejércitos'', el término alcanza dimensión cósmica, abarcando ángeles (Sal 103:21; 148:2) y estrellas como ejércitos de Dios. El alemán Heerscharen (''multitudes de huestes'') preserva la imaginería militar aplicada al ámbito sobrenatural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146291, 'spa', 'Justicia (cualidad ética)', 'La cualidad moral abstracta de ser recto, justo e íntegro: abarca la justicia de Dios (Sal 4:2; Is 41:10), la equidad judicial (Dt 1:16; Pr 31:9), las normas comerciales honestas (Lv 19:36, ''balanzas justas, pesas justas'') y el carácter recto del rey ideal (Is 32:1). El alemán Gerechtigkeit, el francés justice y el español justicia convergen en este sentido ético-jurídico unificado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146292, 'spa', 'Justicia (equidad judicial)', 'Equidad judicial y normas jurídicas: el aspecto de tsedheq que se manifiesta en la administración recta de la ley, el juicio imparcial y la rectitud forense. Dt 1:16 ordena juzgar ''con justicia'', y Pr 31:9 exhorta a abrir la boca por el afligido y ''juzgar con justicia''. Este sentido se superpone con el anterior pero enfatiza el contexto institucional y tribunalicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146293, 'spa', 'Roca, peñasco o risco como formación geológica natural que sirve de referencia, ', 'Roca, peñasco o risco como formación geológica natural que sirve de referencia, refugio, fuente de agua o lugar de abrigo. Este es el sentido físico dominante: Moisés golpea la roca en Horeb (Éx 17:6), Dios coloca a Moisés en la hendidura de la roca (Éx 33:21-22), Balaam contempla a Israel desde la cima de las peñas (Nm 23:9) y las cabras monteses habitan entre los riscos (1 S 24:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146294, 'spa', 'La Roca en sentido metafórico', 'La Roca en sentido metafórico: Dios como protector y refugio. Se solapa con el sentido 2 pero se amplía a contextos donde la imagen de roca resalta la protección y la seguridad que Dios ofrece, sin ser necesariamente un título formal. Incluye expresiones como ''roca de mi salvación'' y ''roca de refugio.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146295, 'spa', 'Gorrión o ave pequeña en contextos proverbiales de libertad y vulnerabilidad', 'Gorrión o ave pequeña en contextos proverbiales de libertad y vulnerabilidad. El ave vaga lejos de su nido (Pr 27:8), escapa de la trampa del cazador (Sal 124:7) y vela sola en un tejado (Sal 102:7). El salmista envidia al gorrión que halla un hogar junto a los altares de Dios (Sal 84:3). En Eclesiastés 12:4, la ''voz del ave'' despierta al anciano. El español distingue ''pájaro'' (ave pequeña) del genérico ''ave''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146296, 'spa', 'Ave en el rito levítico de purificación para enfermedades de la piel y casas con', 'Ave en el rito levítico de purificación para enfermedades de la piel y casas contaminadas (Lv 14:4-7, 49-53). Se requieren ''dos aves vivas y limpias'': una se sacrifica sobre agua corriente y la otra, bañada en la sangre, se suelta viva, creando una imagen vívida de purificación que va de la muerte a la vida. El sustantivo aparece aquí en su forma plural tsipporim.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146297, 'spa', 'Aves o criaturas aladas en sentido genérico colectivo, referido a las aves como ', 'Aves o criaturas aladas en sentido genérico colectivo, referido a las aves como clase de seres vivos. Este uso abarca contextos narrativos y legales donde ''ave'' designa pájaros en general, sin especificación de especie. La evidencia multilingüe muestra que algunas lenguas (francés ''oiseau'', alemán ''Vogel'') usan un solo término genérico, mientras que el español dispone de ''ave'' y ''pájaro''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146298, 'spa', 'Celos divinos', 'Celos divinos: la pretensión exclusiva de Dios sobre Israel, expresada como fuego posesivo contra quienes usurpan su lugar. Ezequiel 36:5 habla del celo ardiente de Dios, y Números 25:11 lo vincula a la ira santa de Fineas. Este sentido refleja la naturaleza pactual de la relación entre Dios e Israel, donde la idolatría constituye una infidelidad que despierta la respuesta celosa divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146299, 'spa', 'Celos humanos', 'Celos humanos: sospecha conyugal o rivalidad posesiva entre personas. El ritual de la sotá (Nm 5:14) describe el ''espíritu de celos'' del esposo, Proverbios 6:34 advierte que ''los celos son el furor del hombre,'' y Cantares 8:6 proclama que ''los celos son crueles como el sepulcro.'' Este sentido abarca la intensidad emocional que surge ante la amenaza de perder lo que uno valora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146300, 'spa', 'cabeza (anatómica)', 'La cabeza física y literal de un ser humano o animal, el sentido por defecto y no marcado, que aparece en aproximadamente el 57% de las ocurrencias. El sueño del panadero en Gn 40:20 y Jacob bendiciendo a Efraín poniendo su mano sobre la cabeza del niño (Gn 48:14) son pasajes clave.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146301, 'spa', 'jefe, cabecilla (figurado)', 'Uso metafórico de ''cabeza'' para designar al principal o supremo en un ámbito político o social. Los pasajes se centran en liderazgo más allá del parentesco: ser puesto como cabeza sobre pueblos o naciones, encabezar una formación o sobresalir entre los demás.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146302, 'spa', 'viento natural', 'Viento como fenómeno meteorológico: el movimiento natural del aire, incluidas brisas, tormentas, los cuatro vientos como fuerzas cósmicas y el viento del este (רוּחַ קָדִים) que seca mares y arrasa cosechas. Árabe رِيح, coreano 바람, hindi हवा y suajili upepo lo aíslan como término puramente atmosférico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (146303, 'spa', 'viento divino', 'El viento como instrumento de la acción de Dios: distinto del viento natural por su función teológica como medio de juicio o salvación. Dios envía un viento sobre las aguas del diluvio (Gn 8:1), un viento del este que parte el mar (Éx 14:21) y ráfagas que ejecutan sentencias proféticas. El agente meteorológico se convierte en herramienta del propósito divino.');